mapper.select:
select u.user_id as userId,u.real_name as realName,u.gender,u.mobile,u.hire_date as hireDate,
       u.email,u.user_status as userStatus,d.dept_name as deptName,u.is_super_admin as isSuperAdmin,
       (select group_concat(a.role_name separator ',')
        from sys_role a
        where json_contains(u.role_ids, cast(a.role_id as json))) as roles
from sys_user u
        left join sys_department d on u.dept_id = d.id


        and u.gender = #{gender}


        and d.id = #{deptId}


        and u.user_status = #{userStatus}


        and exists(
            select 1 from sys_role r
             where json_contains(u.role_ids, cast(r.role_id as json))
             and r.role_id = #{roleId}
        )


        and u.real_name like concat('%',#{realName},'%')


